  businessName: 'Acme Dental',            // <-- edit per client
  timezone: 'America/New_York',
  calendarId: 'primary',
  openDays: [1, 2, 3, 4, 5],              // Luxon weekdays: 1=Mon ... 7=Sun
  openTime: '09:00', closeTime: '17:00',
  slotStepMin: 30, bufferMin: 10, minNoticeMin: 60, maxDaysAhead: 60,
  services: { consultation: 30, checkup: 45, cleaning: 60, emergency: 30 },
  defaultServiceMin: 30,
  assistantId: 'REPLACE_VAPI_ASSISTANT_ID'
} } }];

const { body, cfg } = $input.first().json;
const m = body.message || {};
const call = m.call || body.call || {};
const base = { cfg, callId: call.id || '', callerPhone: (call.customer?.number || '').replace(/[^\d+]/g, '') };
if (m.type === 'tool-calls') {
  const list = m.toolCallList || m.toolCalls || (m.toolWithToolCallList || []).map(t => t.toolCall) || [];
  const tc = list[0];
  if (!tc) return [{ json: { ...base, route: 'ignore' } }];
  let args = tc.arguments ?? tc.function?.arguments ?? {};
  if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
  return [{ json: { ...base, route: 'tool', tool: tc.name || tc.function?.name, toolCallId: tc.id, args } }];
}
if (m.type === 'end-of-call-report') return [{ json: { ...base, route: 'eoc', raw: body } }];
if (m.type === 'assistant-request') return [{ json: { ...base, route: 'assistant' } }];
return [{ json: { ...base, route: 'ignore' } }];

const r = $('Route Message').first().json, cfg = r.cfg;
const lead = (($input.first().json || {}).data || [])[0];
const now = DateTime.now().setZone(cfg.timezone);
const [oh, om] = cfg.openTime.split(':').map(Number), [ch, cm] = cfg.closeTime.split(':').map(Number);
const open = cfg.openDays.includes(now.weekday) && now >= now.set({ hour: oh, minute: om }) && now < now.set({ hour: ch, minute: cm });
return [{ json: { after: 'none', response: { assistantId: cfg.assistantId, assistantOverrides: { variableValues: {
  callerName: lead ? (lead.First_Name || lead.Last_Name || '') : '', isReturning: !!lead,
  currentDate: now.toFormat("cccc, LLLL d, yyyy"), currentTime: now.toFormat('h:mm a'), businessOpen: open, businessName: cfg.businessName } } } } }];

const r = $('Route Message').first().json, cfg = r.cfg, a = r.args || {};
const tz = cfg.timezone, now = DateTime.now().setZone(tz);
let d = a.date ? DateTime.fromISO(a.date, { zone: tz }) : now;
if (!d.isValid) d = now;
d = d.startOf('day'); if (d < now.startOf('day')) d = now.startOf('day');
return [{ json: { cfg, fbBody: { timeMin: d.toUTC().toISO(), timeMax: d.plus({ days: 7 }).endOf('day').toUTC().toISO(), timeZone: tz, items: [{ id: cfg.calendarId }] } } }];

function mk(r, obj, after, extra) {
