const r = $('Route Message').first().json, cfg = r.cfg, a = r.args || {}, tz = cfg.timezone;
const cal = Object.values($input.first().json.calendars || {})[0] || {};
const busy = (cal.busy || []).map(b => ({ s: DateTime.fromISO(b.start), e: DateTime.fromISO(b.end) }));
const dur = cfg.services[String(a.service || '').toLowerCase().trim()] || cfg.defaultServiceMin;
const now = DateTime.now().setZone(tz), earliest = now.plus({ minutes: cfg.minNoticeMin });
let day = a.date ? DateTime.fromISO(a.date, { zone: tz }) : now;
if (!day.isValid) day = now;
day = day.startOf('day'); if (day < now.startOf('day')) day = now.startOf('day');
const pref = String(a.preferredTime || '').toLowerCase().trim();
const [oh, om] = cfg.openTime.split(':').map(Number), [ch, cm] = cfg.closeTime.split(':').map(Number);
function slotsFor(d) {
  if (!cfg.openDays.includes(d.weekday)) return [];
  const out = []; let t = d.set({ hour: oh, minute: om }); const close = d.set({ hour: ch, minute: cm });
  while (t.plus({ minutes: dur }) <= close) {
    const e = t.plus({ minutes: dur });
    const clash = busy.some(b => t < b.e.plus({ minutes: cfg.bufferMin }) && e.plus({ minutes: cfg.bufferMin }) > b.s);
    if (t >= earliest && !clash) out.push(t);
    t = t.plus({ minutes: cfg.slotStepMin });
  }
  return out;
}
function pick(list) {
  let l = list;
  if (pref === 'morning') l = list.filter(t => t.hour < 12);
  else if (pref === 'afternoon') l = list.filter(t => t.hour >= 12);
  else if (/^\d{1,2}:\d{2}$/.test(pref)) {
    const [h, m] = pref.split(':').map(Number), tgt = h * 60 + m;
    l = [...list].sort((x, y) => Math.abs(x.hour * 60 + x.minute - tgt) - Math.abs(y.hour * 60 + y.minute - tgt)).slice(0, 3).sort((x, y) => x.toMillis() - y.toMillis());
  }
  if (!l.length) l = list;
  return l.slice(0, 3);
}
let found = null, foundDay = null;
for (let i = 0; i < 7; i++) { const d = day.plus({ days: i }); const s = slotsFor(d); if (s.length) { found = pick(s); foundDay = d; break; } }
let msg, slots = [];
if (!found) msg = 'There are no openings in the next 7 days. Offer to take a callback request instead.';
else {
  const req = a.date ? DateTime.fromISO(a.date, { zone: tz }) : null;
  const same = !req || !req.isValid || req.hasSame(foundDay, 'day');
  slots = found.map(t => ({ start: t.toISO(), label: t.toFormat('h:mm a') }));
  msg = `${same ? '' : 'Nothing was open on the requested date. '}Available on ${foundDay.toFormat('cccc, LLLL d')}: ${slots.map(s => s.label).join(', ')}. Appointment length ${dur} minutes.`;
}
return [mk(r, { message: msg, slots, durationMin: dur }, 'none')];

